# 1. Arguments the extractor must provide
list_of_arguments_to_read = {
    "tool_name": str,                # name of the tool the agent wants to call
    "entity_id": str,                # ID of the entity being acted on (if applicable)
    "reason": str,                   # reason for adding to blacklist (add_to_blacklist)
    "new_reason": str,               # new reason for updating (update_blacklist_reason)
    "entity_risk_category": str,     # risk tag, e.g. "telecom fraud", "money laundering", etc.
    "verification_results": dict,    # structured results of prior verification tools
    # Example structure:
    # {
    #   "verify_police_notice": {"status": "success", "entity_id": "...", "episode_id": "..."},
    #   "analyze_association": {"status": "success", "entity_id": "...", "episode_id": "...",
    #                           "high_risk_connections": True, "no_high_risk_connections": False},
    #   "query_blacklist_status": {"status": "success", "entity_id": "...",
    #                              "is_blacklisted": False, "episode_id": "..."}
    # }
}

# 2. Policy constants
SAFE_TOOLS = {
    "query_blacklist_status",
    "verify_police_notice",
    "analyze_association",
    "escalate_to_human",
    "reject_request",
}
HIGH_RISK_TOOLS = {
    "add_to_blacklist",
    "remove_from_blacklist",
    "update_blacklist_reason",
}
HIGH_RISK_CATEGORIES = {
    "telecom fraud",
    "money laundering",
    "illegal fundraising",
}
# Required verification steps per high‑risk tool
REQUIRED_STEPS = {
    "add_to_blacklist": ["verify_police_notice", "analyze_association", "query_blacklist_status"],
    "remove_from_blacklist": ["query_blacklist_status", "verify_police_notice"],
    "update_blacklist_reason": ["query_blacklist_status", "analyze_association"],
}
# Additional high‑risk checks (only for entities whose category is in HIGH_RISK_CATEGORIES)
ADDITIONAL_HIGH_RISK_CHECKS = {
    "add_to_blacklist": [],  # already covered by the three base steps
    "remove_from_blacklist": ["analyze_association_no_high_risk"],
    "update_blacklist_reason": ["verify_police_notice"],
}

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Allow or deny a tool call based on required verification results."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing tool_name."

    # Safe tools are always allowed
    if tool in SAFE_TOOLS:
        return True, f"Tool '{tool}' is safe and allowed."

    # If the tool is not one of the high‑risk ones we know about, allow it
    if tool not in HIGH_RISK_TOOLS:
        return True, f"Tool '{tool}' is not covered by the policy and is allowed."

    # From here on we are dealing with a high‑risk, blacklist‑modifying tool
    entity_id = arguments.get("entity_id")
    if not entity_id:
        return False, f"'{tool}' requires a non‑empty entity_id."

    # Gather verification results
    verif = arguments.get("verification_results") or {}
    if not isinstance(verif, dict):
        return False, "verification_results must be a dict."

    # Ensure all base required steps are present and successful
    missing_steps = [step for step in REQUIRED_STEPS[tool] if step not in verif]
    if missing_steps:
        return False, f"Missing required verification steps for '{tool}': {missing_steps}."

    # Helper to check a step's success and matching entity_id
    def step_ok(step_name: str) -> bool:
        step = verif.get(step_name, {})
        return (
            isinstance(step, dict)
            and step.get("status") == "success"
            and step.get("entity_id") == entity_id
        )

    for step in REQUIRED_STEPS[tool]:
        if not step_ok(step):
            return False, f"Verification step '{step}' failed or mismatched entity_id for '{tool}'."

    # Additional checks that depend on risk category
    risk_category = arguments.get("entity_risk_category", "").lower()
    is_high_risk = risk_category in HIGH_RISK_CATEGORIES

    # Specific logic per tool
    if tool == "add_to_blacklist":
        # query_blacklist_status must indicate the entity is NOT already blacklisted
        q_status = verif["query_blacklist_status"]
        if q_status.get("is_blacklisted"):
            return False, "Entity is already blacklisted; cannot add again."
        # For high‑risk entities, ensure the three base steps belong to the same episode
        if is_high_risk:
            ep_ids = {verif[s].get("episode_id") for s in REQUIRED_STEPS[tool]}
            if len(ep_ids) != 1 or None in ep_ids:
                return False, "High‑risk addition requires all verifications in the same episode."
        return True, "All checks passed for add_to_blacklist."

    if tool == "remove_from_blacklist":
        # query_blacklist_status must indicate the entity IS currently blacklisted
        q_status = verif["query_blacklist_status"]
        if not q_status.get("is_blacklisted"):
            return False, "Entity is not currently blacklisted; cannot remove."
        # High‑risk extra check: analyze_association must show no remaining high‑risk connections
        if is_high_risk:
            assoc = verif.get("analyze_association")
            if not assoc or assoc.get("status") != "success":
                return False, "Missing successful analyze_association for high‑risk removal."
            if assoc.get("high_risk_connections"):
                return False, "High‑risk entity still has high‑risk connections; cannot remove."
        return True, "All checks passed for remove_from_blacklist."

    if tool == "update_blacklist_reason":
        # query_blacklist_status must indicate the entity IS blacklisted
        q_status = verif["query_blacklist_status"]
        if not q_status.get("is_blacklisted"):
            return False, "Entity is not blacklisted; cannot update reason."
        # analyze_association must justify the change (e.g., new evidence)
        assoc = verif["analyze_association"]
        if not assoc or assoc.get("status") != "success":
            return False, "Missing successful analyze_association for reason update."
        # For high‑risk entities also require verify_police_notice success
        if is_high_risk and not step_ok("verify_police_notice"):
            return False, "High‑risk reason update requires successful verify_police_notice."
        return True, "All checks passed for update_blacklist_reason."

    # Fallback deny (should not be reached)
    return False, f"Unhandled tool '{tool}'."

